// Generate pi's agent profile from the registry, so pi's view of each model is the one the server runs with.
// A hand-written models.json once claimed a 32,768-token window for a model served at 4,096. That is what made
// agent turns cut off. Here every model's contextWindow comes from discovery, and a model with no known served
// window is skipped and listed, never guessed.
//
// Secrets never enter the generated files. Access headers reference environment variables by name, and env.sh
// reads the token file at run time.
import type { MeshHost } from "./mesh-config.js";
import type { ToolStore } from "./tool-store.js";

export interface PiProfile {
  /** The contents of models.json. */
  models: { providers: Record<string, unknown> };
  /** The contents of env.sh: exports the Access header variables from the token file, with no values in it. */
  envSh: string;
  /** Local models that were skipped, with the reason. Shown to the operator, never silent. */
  skipped: { id: string; reason: string }[];
  /** Access header variable names the profile relies on. */
  headerVars: string[];
}

/** The two env var names for a host's service token: CF_ACCESS_X → CF_ACCESS_X_ID / CF_ACCESS_X_SECRET. */
export function headerVarsFor(serviceTokenEnv: string): { id: string; secret: string } {
  return { id: `${serviceTokenEnv}_ID`, secret: `${serviceTokenEnv}_SECRET` };
}

/** The provider key for a host: a stable, lowercase name, never a model name. */
const providerKey = (host: string) => `mesh-${host.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;

export function buildPiProfile(store: ToolStore, mesh: MeshHost[]): PiProfile {
  const providers: Record<string, unknown> = {};
  const skipped: { id: string; reason: string }[] = [];
  const headerVars: string[] = [];

  for (const cap of store.tools.filter((t) => t.enabled && t.kind === "llm" && t.source === "mesh")) {
    if (cap.servedContext === undefined) {
      skipped.push({ id: cap.name, reason: "the served context window is unknown; re-run discovery for this host" });
      continue;
    }
    const key = providerKey(cap.host);
    const meshHost = mesh.find((h) => h.name === cap.host);
    const headers: Record<string, string> = {};
    if (meshHost?.serviceTokenEnv) {
      const v = headerVarsFor(meshHost.serviceTokenEnv);
      headers["CF-Access-Client-Id"] = `$${v.id}`;
      headers["CF-Access-Client-Secret"] = `$${v.secret}`;
      headerVars.push(v.id, v.secret);
    }
    const provider = (providers[key] ??= {
      baseUrl: `${cap.address.replace(/\/+$/, "")}/v1`,
      api: "openai-completions",
      apiKey: "unused-behind-access",
      ...(Object.keys(headers).length ? { headers } : {}),
      models: [],
    }) as { models: { id: string; contextWindow: number; maxTokens: number }[] };
    // The output cap is half the window: a turn keeps room for the prompt, the tool schemas and the history.
    provider.models.push({ id: cap.model, contextWindow: cap.servedContext, maxTokens: Math.max(256, Math.floor(cap.servedContext / 2)) });
  }

  const tokenEnvs = [...new Set(mesh.filter((h) => h.serviceTokenEnv).map((h) => h.serviceTokenEnv!))];
  const lines = [
    "# Generated by apps/dpi-mcp: exports the Access header variables from the token file. Holds no values itself.",
    "set -a; . \"$HOME/.dpi-mcp/access.env\"; set +a",
    ...tokenEnvs.map((e) => {
      const v = headerVarsFor(e);
      return `export ${v.id}="\${${e}%%:*}" ${v.secret}="\${${e}#*:}"`;
    }),
    "",
  ];

  return {
    models: { providers },
    envSh: lines.join("\n"),
    skipped,
    headerVars: [...new Set(headerVars)],
  };
}
